/**
 * A MINUS right operand is a bottom-up scope boundary: bindings that a correlated enclosing operator (OPTIONAL, a
 * joined group) carries into the MINUS must only constrain the right operand on the names MINUS actually compares (the
 * output names shared by both operands). Any other pushed-in binding is a selection on a variable that is fresh inside
 * the right operand and changes the result. LATERAL is the one exception: its substituted input names are constants
 * throughout the right-hand side, MINUS operands included. Expected bags are hand-computed from SPARQL 1.1 section 18.5
 * and the SPARQL 1.2 LATERAL substitution semantics.
 */
class MinusInsideCorrelatedOperatorScopeTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String PREFIX = "PREFIX : <urn:ex:>\n";

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	private static IRI iri(String local) {
		return VF.createIRI("urn:ex:" + local);
	}

	@ParameterizedTest(name = "condition={0}")
	@ValueSource(strings = { "", "FILTER(BOUND(?y))", "FILTER(?y != ?s)" })
	void minusInsideOptionalIsEvaluatedIndependently(String condition) {
		add(iri("a"), iri("p"), iri("z1"));
		add(iri("a"), iri("q"), iri("b"));
		add(iri("b"), iri("r"), iri("z2"));
		// OPTIONAL operand: {s=a,y=b} MINUS {y=b,z=z2} is empty (shared y), so the left row stays unextended
		String query = PREFIX + """
				SELECT ?s ?z ?y WHERE {
				  ?s :p ?z
				  OPTIONAL { ?s :q ?y MINUS { ?y :r ?z } %s }
				}
				""".formatted(condition);
		assertThat(rows(query)).containsExactly("{s=urn:ex:a, z=urn:ex:z1}");
	}

	@Test
	void minusInsideOptionalStillRemovesOnSharedNamesWhenOuterBindingMatches() {
		add(iri("a"), iri("p"), iri("z2"));
		add(iri("a"), iri("q"), iri("b"));
		add(iri("b"), iri("r"), iri("z2"));
		// The correlated evaluation happens to agree with bottom-up semantics here: the left row must stay bare.
		String query = PREFIX + """
				SELECT ?s ?z ?y WHERE {
				  ?s :p ?z
				  OPTIONAL { ?s :q ?y MINUS { ?y :r ?z } }
				}
				""";
		assertThat(rows(query)).containsExactly("{s=urn:ex:a, z=urn:ex:z2}");
	}

	@Test
	void minusInsideOptionalKeepsExtensionWhenRightOperandHasNoCompatibleRow() {
		add(iri("a"), iri("p"), iri("z1"));
		add(iri("a"), iri("q"), iri("b"));
		add(iri("c"), iri("r"), iri("z1"));
		// {s=a,y=b} MINUS {y=c,z=z1}: y differs, so nothing is removed and the OPTIONAL extends the row
		String query = PREFIX + """
				SELECT ?s ?z ?y WHERE {
				  ?s :p ?z
				  OPTIONAL { ?s :q ?y MINUS { ?y :r ?z } }
				}
				""";
		assertThat(rows(query)).containsExactly("{s=urn:ex:a, y=urn:ex:b, z=urn:ex:z1}");
	}

	@Test
	void minusInsideJoinedGroupIsEvaluatedIndependentlyOfOuterBinding() {
		add(iri("a"), iri("x"), iri("w1"));
		add(iri("s1"), iri("q"), iri("y1"));
		add(iri("y1"), iri("r"), iri("w2"));
		// group: {s=s1,y=y1} MINUS {y=y1,w=w2} is empty, so the join produces nothing
		String query = PREFIX + """
				SELECT ?a ?w ?s ?y WHERE {
				  ?a :x ?w .
				  { ?s :q ?y MINUS { ?y :r ?w } }
				}
				""";
		assertThat(rows(query)).isEmpty();
	}

	@Test
	void minusUnderOptionalInsideNestedOptionalGroupIsEvaluatedIndependently() {
		add(iri("a"), iri("p"), iri("z1"));
		add(iri("a"), iri("q"), iri("b"));
		add(iri("b"), iri("r"), iri("z2"));
		String query = PREFIX + """
				SELECT ?s ?z ?y WHERE {
				  ?s :p ?z
				  OPTIONAL { OPTIONAL { ?s :q ?y MINUS { ?y :r ?z } } }
				}
				""";
		assertThat(rows(query)).containsExactly("{s=urn:ex:a, z=urn:ex:z1}");
	}

	@Test
	void nonAssuredSharedNameIsNotPushedIntoMinusRightOperand() {
		add(iri("t"), iri("x"), iri("y1"));
		add(iri("a"), iri("p"), iri("y1"));
		add(iri("a"), iri("a"), iri("b"));
		// Bottom-up the MINUS right operand is {s=a,b=b} (a has no :c edge, so ?y stays unbound and the filter
		// passes); it is compatible with {s=a,y=y1} on ?s, the row is removed and the OPTIONAL stays bare. Pushing the
		// correlated y=y1 into the operand would re-extend the unmatched OPTIONAL row with y and fail the BOUND filter.
		String query = PREFIX + """
				SELECT ?t ?y ?s WHERE {
				  ?t :x ?y
				  OPTIONAL { ?s :p ?y MINUS { ?s :a ?b OPTIONAL { ?s :c ?y } FILTER(!BOUND(?y)) } }
				}
				""";
		assertThat(rows(query)).containsExactly("{t=urn:ex:t, y=urn:ex:y1}");
	}

	@Test
	void lateralSubstitutedInputIsPushedIntoMinusRightOperand() {
		add(iri("a"), iri("p"), iri("z1"));
		add(iri("a"), iri("q"), iri("b"));
		add(iri("b"), iri("r"), iri("z2"));
		// Under LATERAL, ?z is substituted (z1) in the whole right-hand side: { ?y :r z1 } is empty, so MINUS removes
		// nothing and the LATERAL join yields the extended row.
		String query = PREFIX + """
				SELECT ?s ?z ?y WHERE {
				  ?s :p ?z
				  LATERAL { ?s :q ?y MINUS { ?y :r ?z } }
				}
				""";
		assertThat(rows(query)).containsExactly("{s=urn:ex:a, y=urn:ex:b, z=urn:ex:z1}");
	}

	@Test
	void lateralSubstitutedInputMatchingMinusRightOperandRemovesRow() {
		add(iri("a"), iri("p"), iri("z1"));
		add(iri("a"), iri("q"), iri("b"));
		add(iri("b"), iri("r"), iri("z1"));
		// { ?y :r z1 } yields {y=b}, compatible with {s=a,y=b}: MINUS removes the row and LATERAL yields nothing.
		String query = PREFIX + """
				SELECT ?s ?z ?y WHERE {
				  ?s :p ?z
				  LATERAL { ?s :q ?y MINUS { ?y :r ?z } }
				}
				""";
		assertThat(rows(query)).isEmpty();
	}

	private void add(IRI subject, IRI predicate, Value object) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, object);
		}
	}

	private List<String> rows(String query) {
		List<String> rows = new ArrayList<>();
		try (SailRepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				BindingSet bindingSet = result.next();
				TreeMap<String, String> sorted = new TreeMap<>();
				for (String name : bindingSet.getBindingNames()) {
					Value value = bindingSet.getValue(name);
					if (value != null) {
						sorted.put(name, value.stringValue());
					}
				}
				rows.add(sorted.toString());
			}
		}
		rows.sort(Comparator.naturalOrder());
		return rows;
	}
}
